"use client";

/**
 * Amplify client setup. `amplify_outputs.json` is generated by the backend
 * deploy (Amplify Hosting writes it during the build; locally run
 * `npx ampx generate outputs --app-id <id> --branch <branch> --out-dir apps/web`).
 * When it's empty the app runs in demo mode on local browser storage.
 */
import { Amplify } from "aws-amplify";
import "aws-amplify/auth/enable-oauth-listener";
import { generateClient } from "aws-amplify/data";
import type { Schema } from "../../../amplify/data/resource";
import outputs from "../amplify_outputs.json";
import { localizeError } from "./i18n-current";

export const backendEnabled = Boolean((outputs as { auth?: unknown }).auth);

/**
 * Sign-in runs on our own address (auth.mygiftlockers.com, a Cognito custom domain set up in
 * amplify/backend.ts) so Google's account chooser says "continue to mygiftlockers.com". The
 * generated outputs still name Cognito's prefix domain, which keeps working as a fallback.
 */
export const AUTH_DOMAIN = "auth.mygiftlockers.com";
const withAuthDomain = (o: typeof outputs) => {
  const auth = (o as { auth?: { oauth?: { domain?: string } } }).auth;
  return auth?.oauth ? { ...o, auth: { ...auth, oauth: { ...auth.oauth, domain: AUTH_DOMAIN } } } : o;
};

if (backendEnabled && typeof window !== "undefined") {
  Amplify.configure(withAuthDomain(outputs) as Parameters<typeof Amplify.configure>[0], { ssr: false });
}

let _client: ReturnType<typeof generateClient<Schema>> | null = null;
/** Typed data client. Signed-in calls use the user pool; link-holder calls pass authMode "apiKey". */
export function api() {
  if (!backendEnabled) throw new Error("Backend not configured");
  _client ??= generateClient<Schema>();
  return _client;
}

/** Custom operations return a.json(); depending on the transport that's a string or an object. */
export function parseJson<T>(v: unknown): T {
  return (typeof v === "string" ? JSON.parse(v) : v) as T;
}

/** Turn `{ data, errors }` + our `{ error }` payloads into a value or a thrown Error. */
export function unwrap<T>(res: { data?: unknown; errors?: readonly { message: string }[] | null }): T {
  if (res.errors?.length) throw new Error(res.errors[0]!.message);
  const value = parseJson<T & { error?: string }>(res.data);
  if (value && typeof value === "object" && "error" in value && value.error) throw new Error(localizeError(value.error));
  return value as T;
}
